BEGIN;

SET LOCAL check_function_bodies = on;

SET LOCAL lc_messages = 'C';

CREATE ROLE anon NOLOGIN;

CREATE ROLE authenticated NOLOGIN;

CREATE ROLE service_role NOLOGIN;

CREATE TABLE public.land_use_plans (plan_context jsonb, geography_label text, geography_geojson jsonb);

DO $compiler$
DECLARE
  case_name text;
  expected_state text;
  caught_state text;
  caught_message text;
  caught_context text;
  compiled boolean;
BEGIN
  IF current_setting('server_version_num') <> '170006' THEN
    RAISE EXCEPTION 'M424 wrong PostgreSQL version: %', current_setting('server_version_num');
  END IF;
  RAISE NOTICE 'M424 VERSION %', version();
  FOR case_name, expected_state IN
    SELECT * FROM (VALUES
      ('01-harmless', 'ZP001'),
      ('02-fixed', 'ZP001'),
      ('03-original', '42601'),
      ('04-restored', 'ZP001')
    ) AS cases(name, state)
  LOOP
    caught_state := NULL;
    caught_message := NULL;
    caught_context := NULL;
    compiled := false;
    BEGIN
      EXECUTE pg_read_file('/inputs/' || case_name || '.sql');
      compiled := true;
      RAISE EXCEPTION USING ERRCODE = 'ZP001', MESSAGE = 'M424 rollback compiled DDL';
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS caught_state = RETURNED_SQLSTATE,
        caught_message = MESSAGE_TEXT, caught_context = PG_EXCEPTION_CONTEXT;
    END;
    IF caught_state IS DISTINCT FROM expected_state THEN
      RAISE EXCEPTION 'M424 case=% wrong SQLSTATE=% expected=% message=% context=%',
        case_name, caught_state, expected_state, caught_message, caught_context;
    END IF;
    IF expected_state = 'ZP001' AND
      (NOT compiled OR caught_message IS DISTINCT FROM 'M424 rollback compiled DDL') THEN
      RAISE EXCEPTION 'M424 case=% did not compile completely', case_name;
    END IF;
    IF expected_state = '42601' AND
      (compiled OR caught_message IS DISTINCT FROM 'syntax error at end of input') THEN
      RAISE EXCEPTION 'M424 original did not fail for the saved parser reason: %', caught_message;
    END IF;
    IF to_regprocedure('public.guard_land_use_plan_context_geography()') IS NOT NULL
      OR EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.land_use_plans'::regclass
        AND tgname = 'land_use_plan_context_zz_geography') THEN
      RAISE EXCEPTION 'M424 case=% subtransaction did not roll back DDL', case_name;
    END IF;
    RAISE NOTICE 'M424 CASE % EXPECTED % OBSERVED % MESSAGE %',
      case_name, expected_state, caught_state, caught_message;
    IF expected_state = '42601' THEN
      RAISE NOTICE 'M424 ORIGINAL CONTEXT %', caught_context;
    END IF;
  END LOOP;
  RAISE NOTICE 'M424 ALL_FOUR_CASES_OK';
END;
$compiler$;

ROLLBACK;

DO $rollback$
BEGIN
  IF to_regclass('public.land_use_plans') IS NOT NULL
    OR to_regprocedure('public.guard_land_use_plan_context_geography()') IS NOT NULL
    OR EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) THEN
    RAISE EXCEPTION 'M424 outer rollback left synthetic objects';
  END IF;
  RAISE NOTICE 'M424 ROLLBACK_CONFIRMED';
END;
$rollback$;
